onRoleReachedMoon = function()     game.pauseLogic()	if global.getBool("lvl22_b1") then dialog.setSkipEnabled(true) end		repeat			sound.play("52-1")		    if dialog.show("Level22-1", faceZhoumei) ==1 then break end			sound.play("46-1")			if dialog.show("Level22-2", faceRenzhen) ==1 then break end			if dialog.show("Level22-3", faceRenzhen) ==1 then break end			if dialog.show("Level22-4", faceZhoumei) ==1 then break end			sound.play("51-2")		    if dialog.show("Level22-5", faceBujie) ==1 then break end			if dialog.show("Level22-6", faceQidao) ==1 then break end			global.setBool("lvl22_b1")		until true		dialog.setSkipEnabled(false)    game.success()end